use vstd::prelude::*;

verus! {

fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
    ensures
        b@ == a@,
        b@.len() == a@.len(),
{
    let mut b: Vec<u64> = Vec::with_capacity(a.len());

    for &x in a.iter()
        invariant
            // The portion copied so far matches the corresponding prefix of `a`
            b@ == a@.subrange(0, b@.len() as int),
            b@.len() <= a@.len(),
            // Strengthen: length relationship at the Rust level too
            b.len() == b@.len(),
            a.len() == a@.len(),
    {
        b.push(x);

        // After pushing one element, the spec-view `b@` extends by that element.
        // The loop invariant then re-establishes that this equals the next prefix of `a@`.
        assert(b@.len() <= a@.len());
    }

    b
}

}

